const q = $json.query || {};
const expected = 'REPLACE_WITH_VERIFY_TOKEN';
const ok = q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === expected;
return [{ json: { ok, challenge: ok ? String(q['hub.challenge'] || '') : 'Verification failed' } }];

const body = $json.body || $json;
const value = body.entry?.[0]?.changes?.[0]?.value || {};
const message = value.messages?.[0];
if (!message?.id || message.type !== 'text') return [];
const state = $getWorkflowStaticData('global');
state.seen ||= {};
if (state.seen[message.id]) return [];
state.seen[message.id] = Date.now();
for (const [id, at] of Object.entries(state.seen)) if (Date.now() - at > 604800000) delete state.seen[id];
const sender = String(message.from || '').replace(/\D/g, '');
const text = String(message.text?.body || '').trim();
if (!sender || !text) return [];
const wantsDesigns = /(design|catalog|rate|rates|price|prices|fabric|collection|dikhao|bhejo|bhav|daam)/i.test(text);
return [{ json: { sender, text, messageId: message.id, wantsDesigns } }];

const request = $('Parse Message').first().json;
if (!request.wantsDesigns) {
  return [{ json: { payload: { messaging_product: 'whatsapp', to: request.sender, type: 'text', text: { body: 'Namaste! Send DESIGN, CATALOG, RATE or PRICE and I will share our latest available designs with rates.' } } } }];
}
const catalog = $('Get Active Designs').first().json.designs || [];
const prices = $json.prices || {};
const stem = name => String(name || '').replace(/\.[^.]+$/, '');
const priceFor = design => {
  const name = String(design.name || ''); const id = String(design.design_id || ''); const base = stem(name);
  for (const key of [id, name, base, id.toLowerCase(), name.toLowerCase(), base.toLowerCase()]) {
    if (key && Object.prototype.hasOwnProperty.call(prices, key) && Number(prices[key]) > 0) return Number(prices[key]);
  }
  return null;
};
const selected = catalog.map(d => ({ ...d, rate: priceFor(d) })).filter(d => d.rate != null).slice(0, 3);
if (!selected.length) return [{ json: { payload: { messaging_product: 'whatsapp', to: request.sender, type: 'text', text: { body: 'New designs are being updated. Please message us again shortly or ask for a salesperson.' } } } }];
return selected.map((design, index) => ({ json: { payload: { messaging_product: 'whatsapp', to: request.sender, type: 'image', image: { link: design.url, caption: `Design ${index + 1} · ₹${design.rate.toLocaleString('en-IN')}\nView: https://chandni-catalog.pages.dev/share?id=${encodeURIComponent(design.design_id)}\nReply MORE for more designs.` } } } }));
